public sealed class Balance {
    private readonly Lock _gate = new();        // C# 13 / .NET 9
    private decimal _amount;
    private int _ops;

    public void Credit(decimal delta) {
        lock (_gate) { _amount += delta; _ops++; }   // one critical section
    }
    public decimal Snapshot() {
        lock (_gate) { return _amount; }             // copy out
    }
}

